import itertools

edges = [
    (0,3), (1,2), (1,4), (1,9),
    (5,11), (6,12), (7,13), (8,11), (10,12)
]

n = 14
# Build adjacency list
adj = [set() for _ in range(n)]
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

# Check degrees
print("Degrees:", [len(adj[i]) for i in range(n)])
print("Min degree:", min(len(adj[i]) for i in range(n)))

# Check max clique size <= 4
def max_clique_size(adj):
    n = len(adj)
    max_size = 0
    # brute force all subsets up to size 5 to check for K5
    for r in range(1, 6):
        for subset in itertools.combinations(range(n), r):
            ok = True
            for i in range(r):
                for j in range(i+1, r):
                    if subset[j] not in adj[subset[i]]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                max_size = max(max_size, r)
    return max_size

print("Max clique size:", max_clique_size(adj))

# Check chromatic number <= 5 using brute force coloring
def is_k_colorable(adj, k):
    n = len(adj)
    colors = [-1]*n
    def dfs(v):
        if v == n:
            return True
        for c in range(k):
            ok = True
            for u in adj[v]:
                if colors[u] == c:
                    ok = False
                    break
            if ok:
                colors[v] = c
                if dfs(v+1):
                    return True
                colors[v] = -1
        return False
    return dfs(0)

print("5-colorable:", is_k_colorable(adj, 5))
print("4-colorable:", is_k_colorable(adj, 4))
print("3-colorable:", is_k_colorable(adj, 3))
print("2-colorable:", is_k_colorable(adj, 2))
